function middleSnake(A, B, a0, ae, b0, be) {
  const N = ae - a0, M = be - b0;
  const max = N + M;
  const off = max + 1;
  const vf = new Int32Array(2 * max + 3);
  const vr = new Int32Array(2 * max + 3);
  const delta = N - M;
  const odd = delta & 1;
  const half = Math.ceil(max / 2);
  for (let d = 0; d <= half; d++) {
    for (let k = -d; k <= d; k += 2) {
      let x;
      if (k === -d || (k !== d && vf[off + k - 1] < vf[off + k + 1])) x = vf[off + k + 1];
      else x = vf[off + k - 1] + 1;
      let y = x - k;
      while (x < N && y < M && A[a0 + x] === B[b0 + y]) { x++; y++; }
      vf[off + k] = x;
      if (odd) {
        const kp = delta - k;
        if (kp >= 1 - d && kp <= d - 1) {
          const xr = N - vr[off + kp];
          if (x >= xr) return { x, y: x - k, u: xr, v: xr - k };
        }
      }
    }
    for (let kp = -d; kp <= d; kp += 2) {
      let xp;
      if (kp === -d || (kp !== d && vr[off + kp - 1] < vr[off + kp + 1])) xp = vr[off + kp + 1];
      else xp = vr[off + kp - 1] + 1;
      let yp = xp - kp;
      // extend snake backwards in real coords
      let x = N - xp, y = M - yp;
      while (x > 0 && y > 0 && A[a0 + x - 1] === B[b0 + y - 1]) { x--; y--; }
      vr[off + kp] = N - x;
      if (!odd) {
